import base64
import numpy as np
import re

def unpack(s):
    return list(
        __import__("itertools").chain(
            *[[1 & (ord(c) >> i) for i in range(8)] for c in s]
        )
    )

def deserialize_mat(serialized):
    dims, data = serialized.strip().split(";")
    dims = map(int, dims.split(","))
    raw_data = base64.b64decode(data)
    unpacked = np.array(unpack(raw_data)).reshape(dims)
    return unpacked

