            encoded_data = cleaned_data[start:end]

            # Decode Base64 and deserialize
            try:
                deserialized_data = deserialize_mat(encoded_data)
                results[component] = {
                    "shape": deserialized_data.shape,
                    "dtype": str(deserialized_data.dtype),
                    "content_sample": deserialized_data.flatten()[:10].tolist()
                }
            except Exception as e:
                results[component] = {"error": str(e)}

